export const GRAMMAR_PARSER_ERROR_HEADER_MESSAGE = (reason: string) => `Failed to parse grammar: ${reason}`;
import {
  buildErrorPosition,
} from "./build-error-position.js";

export class GrammarParseError extends Error {
  grammar: string;
  pos: number;
  reason: string;
